import 'package:flutter/material.dart';
import 'package:flutter_svg/flutter_svg.dart';

import '../../app/theme/navia_tokens.dart';

/// The Navia mark: an arrowhead leaving an origin ring on a blue-to-aqua
/// disc. Source: `assets/brand/navia_logo.svg`, generated by
/// `tool/brand/generate_brand_assets.py` together with the launcher icons.
class NaviaLogoMark extends StatelessWidget {
  const NaviaLogoMark({super.key, this.size = 36});

  static const asset = 'assets/brand/navia_logo.svg';

  final double size;

  @override
  Widget build(BuildContext context) {
    return SvgPicture.asset(
      asset,
      width: size,
      height: size,
      excludeFromSemantics: true,
    );
  }
}

/// Logo mark followed by the "Navia" wordmark.
class NaviaWordmark extends StatelessWidget {
  const NaviaWordmark({super.key, this.markSize = 32});

  final double markSize;

  @override
  Widget build(BuildContext context) {
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        NaviaLogoMark(size: markSize),
        const SizedBox(width: NaviaSpacing.sm),
        Text(
          'Navia',
          style: Theme.of(context).textTheme.titleLarge?.copyWith(
            fontWeight: FontWeight.w800,
            letterSpacing: -0.3,
          ),
        ),
      ],
    );
  }
}
